const leftMenu:[string,IconName][] = [["دخل إضافي","income"],["توزيع الثياب","delivery"],["ملاحظات جديدة","notes"],["تقارير مالية","report"],["الصلاحيات","access"],["المخزون","inventory"],["سجل التشغيل","history"]];
