  function Icon({name}:{name:IconName}){
  const common={fill:"none",stroke:"currentColor",strokeWidth:1.8,strokeLinecap:"round" as const,strokeLinejoin:"round" as const};
  const paths:Record<IconName,ReactNode>={person:<><circle cx="10" cy="8" r="3"/><path d="M4 19c.8-3.4 2.8-5 6-5s5.2 1.6 6 5"/><path d="M18 9v6M15 12h6"/></>,search:<><circle cx="10" cy="10" r="5"/><path d="m14 14 5 5"/></>,whatsapp:<><path d="M18.5 10.5a8.5 8.5 0 0 1-10.7 8.2L4 20l1.3-3.6A8.5 8.5 0 1 1 18.5 10.5Z"/><path d="M8 8.3c.5 2.8 2.4 4.6 5.2 5.2l1.3-1.1 1.6.8c-.4 1.6-1.4 2-2.4 1.7-3.9-1.2-6.3-3.6-7.4-7.4-.3-1 .1-2 1.7-2.4l.8 1.6Z"/></>,finance:<><path d="M3.5 7.5h17v11h-17z"/><path d="M3.5 10h17M8 15h3"/></>,supplier:<><path d="M4 9h16v11H4z"/><path d="M7 9V6h10v3M8 14h8"/></>,income:<><path d="M4 16 9 11l3 3 7-8"/><path d="M14 6h5v5"/></>,delivery:<><path d="M3 8h11v9H3zM14 11h3l3 3v3h-6z"/><circle cx="7" cy="18" r="1.5"/><circle cx="17" cy="18" r="1.5"/></>,notes:<><path d="M5 3.5h14v17H5z"/><path d="M8 8h8M8 12h8M8 16h5"/></>,report:<><path d="M4 20V4"/><path d="M7 17v-5M12 17V8M17 17V5"/></>,access:<><path d="M12 3 19 6v5c0 4.2-2.6 7.3-7 10-4.4-2.7-7-5.8-7-10V6z"/><path d="M9.5 12 11 13.5l3.5-4"/></>,inventory:<><path d="m4 8 8-4 8 4-8 4zM4 8v8l8 4 8-4V8M12 12v8"/></>,late:<><path d="M12 3v9l4 2"/><circle cx="12" cy="12" r="9"/><path d="M5 20 3 22M19 20l2 2"/></>,bulk:<><circle cx="8" cy="8" r="3"/><circle cx="17" cy="9" r="2.5"/><path d="M2.5 19c.6-3.4 2.4-5 5.5-5s4.9 1.6 5.5 5M14 15h7M18 12l3 3-3 3"/></>,history:<><circle cx="12" cy="12" r="8"/><path d="M12 7v5l3 2M5 5 3 5"/></>};
  return <svg viewBox="0 0 24 24" aria-hidden="true" {...common}>{paths[name]}</svg>;
}
  function MenuCard({label,icon,onSelect}:{label:string;icon:IconName;onSelect?:()=>void}){return <button className={`nav-card ${onSelect?"is-enabled":"is-locked"}`} type="button" onClick={onSelect} aria-disabled={!onSelect} tabIndex={onSelect?0:-1}><span className="nav-icon"><Icon name={icon}/></span><span>{label}</span></button>}

type SheetProps={customer:Customer;invoice:InvoiceRecord|null;weight:string;deliveryDate:string;totalThobes:string;measurements:Record<string,string>;fabric:Record<string,string>;fabricMeters:string;designs:Record<string,DesignOption|undefined>;thobeType:string;sleeveMode:SleeveMode;collarMode:CollarMode;neckButtonCount:"1"|"2";neckButtonType:NeckButtonType;workerName:string;sizeCategory:ThobeSize;notes:string;sheetLabel?:string};
  function MeasurementSheet(props:SheetProps){
  const sleeveCategory=props.sleeveMode==="سادة"?"اليد السادة":"الكبك";
  const collarCategory=props.collarMode==="قلاب"?"القلاب":props.collarMode==="سادة"?"الرقبة السادة":"";
  const paperPhoto=(category:string,fallback:string)=>{const option=props.designs[category];return <figure className="paper-feature-photo">{option?<img src={option.imageData} alt={option.name}/>:<span>بدون صورة</span>}<figcaption>{option?.name||fallback}</figcaption></figure>};
  const paperRows=(fields:readonly string[])=>fields.map(field=><p key={field}><span>{field}</span><b className="numeric">{props.measurements[field]||"—"}</b></p>);
  return <article className="paper measurement-paper" dir="rtl">
    <header><div><b>ورقة مقاسات الخياط</b><small>TAILOR {props.sheetLabel&&`— ${props.sheetLabel}`}</small></div><div><strong>رقم الفاتورة: <span className="numeric">{props.invoice?sequenceNumber(props.invoice.invoiceNumber):"مسودة"}</span></strong><small className="numeric">{shortDateFormat.format(new Date())}</small></div></header>
    <section className="paper-customer"><span>العميل: <b>{props.customer.name}</b></span><span>رقم العميل: <b className="numeric">{sequenceNumber(props.customer.code)}</b></span><span>الجوال: <b className="numeric">{props.customer.phone}</b></span><span>تاريخ التفصيل: <b className="numeric">{props.invoice?shortDateFormat.format(databaseDate(props.invoice.createdAt)):shortDateFormat.format(new Date())}</b></span><span>تاريخ التسليم: <b className="numeric">{props.deliveryDate||"—"}</b></span><span>الوزن: <b className="numeric">{props.weight||"—"}</b></span><span>عدد الثياب: <b className="numeric">{props.totalThobes||"1"}</b></span><span>حجم الثوب: <b>{props.sizeCategory}</b></span><span>عامل القص: <b>{props.workerName||"—"}</b></span></section>
    <section className="paper-work-grid">
      <article className="paper-work-card"><h3>الثوب والجسم</h3>{paperPhoto("نوع الثوب",props.thobeType)}<div className="paper-values"><p><span>نوع الثوب</span><b>{props.thobeType}</b></p><p><span>الطول — أمام / خلف</span><b className="numeric">{props.measurements["طول أمام"]||"—"} / {props.measurements["طول خلف"]||"—"}</b></p>{paperRows(bodySingleFields)}</div></article>
      <article className="paper-work-card"><h3>اليد</h3>{paperPhoto(sleeveCategory,props.sleeveMode)}<div className="paper-values"><p><span>نوع اليد</span><b>{props.sleeveMode}</b></p>{paperRows(sleeveBaseFields)}{paperRows(props.sleeveMode==="سادة"?sleevePlainFields:sleeveCuffFields)}</div></article>
      <article className="paper-work-card"><h3>الرقبة</h3>{props.collarMode!=="بدون رقبة"&&paperPhoto(collarCategory,props.collarMode)}<div className="paper-values"><p><span>نوع الرقبة</span><b>{props.collarMode}</b></p>{props.collarMode!=="بدون رقبة"&&<>{paperRows(["محيط الرقبة"])}{props.collarMode==="قلاب"?<p><span>مقاس القلاب</span><b className="numeric">{props.measurements["مقاس القلاب الأول"]||"—"} — {props.measurements["مقاس القلاب الثاني"]||"—"}</b></p>:paperRows(["مقاس الرقبة السادة"])}<p><span>أزرار الرقبة</span><b><span className="numeric">{props.neckButtonCount}</span> — {props.neckButtonType}</b></p></>}</div></article>
      <article className="paper-work-card paper-detail-card"><h3>الجيب والقماش</h3><div className="paper-double-photo">{paperPhoto("الجيب","بدون جيب")}{paperPhoto("السحب","بدون سحب")}</div><div className="paper-values">{fabricFields.map(field=><p key={field}><span>{field}</span><b className={field==="اسم القماش"?"":"numeric"}>{props.fabric[field]||"—"}</b></p>)}<p><span>استهلاك القماش</span><b className="numeric">{props.fabricMeters?`${props.fabricMeters} متر`:"قماش العميل"}</b></p>{props.notes&&<p className="paper-note"><span>ملاحظة</span><b>{props.notes}</b></p>}</div></article>
    </section>
  </article>;
}
  function CustomerReceiptSheet({customer,invoice,thobes,total,paid,discount,remaining,paymentMethod,deliveryDate}:{customer:Customer;invoice:InvoiceRecord|null;thobes:ThobeDraft[];total:number;paid:number;discount:number;remaining:number;paymentMethod:string;deliveryDate:string}){
    // Several garments must stay legible: each group gets its own upper half of an A4 page.
    const pageSize=10;
    const pageCount=Math.max(1,Math.ceil(thobes.length/pageSize));
    return <div className="customer-receipt-stack">{Array.from({length:pageCount},(_,pageIndex)=><article key={pageIndex} className="paper receipt-paper customer-receipt" dir="rtl"><h2>أناقة التميز</h2><p>فاتورة السعر للعميل {pageCount>1&&`— صفحة ${pageIndex+1} من ${pageCount}`}</p><hr/><div><span>رقم الفاتورة</span><b className="numeric">{invoice?sequenceNumber(invoice.invoiceNumber):"مسودة"}</b></div><div><span>رقم العميل</span><b className="numeric">{sequenceNumber(customer.code)}</b></div><div><span>اسم العميل</span><b>{customer.name}</b></div><div><span>رقم الجوال</span><b className="numeric">{customer.phone}</b></div><div><span>عدد الثياب</span><b className="numeric">{numberFormat.format(thobes.length)}</b></div><div><span>تاريخ التفصيل</span><b className="numeric">{invoice?shortDateFormat.format(databaseDate(invoice.createdAt)):shortDateFormat.format(new Date())}</b></div><div><span>تاريخ التسليم</span><b className="numeric">{deliveryDate||"—"}</b></div><hr/><section className="receipt-thobes">{thobes.slice(pageIndex*pageSize,(pageIndex+1)*pageSize).map((thobe,index)=><p key={index}><b>الثوب <span className="numeric">{pageIndex*pageSize+index+1}</span></b><span>{thobe.thobeType} · {thobe.sleeveMode} · {thobe.designs[thobe.collarMode==="قلاب"?"القلاب":"الرقبة السادة"]?.name||thobe.collarMode}{thobe.fabric["اسم القماش"]?` · ${thobe.fabric["اسم القماش"]}`:""}{thobe.fabricMeters?` · ${thobe.fabricMeters} متر`:""}</span></p>)}</section><hr/><div><span>الإجمالي</span><b className="numeric">{numberFormat.format(total)} ر.س</b></div><div><span>المدفوع — {paymentMethod}</span><b className="numeric">{numberFormat.format(paid)} ر.س</b></div><div><span>الخصم</span><b className="numeric">{numberFormat.format(discount)} ر.س</b></div><div className="receipt-total"><span>المتبقي</span><b className="numeric">{numberFormat.format(remaining)} ر.س</b></div><hr/><small>شكرًا لاختياركم أناقة التميز</small></article>)}</div>
  }

  function LaundryReceiptSheet({customer,invoice,thobe,index,total,deliveryDate}:{customer:Customer;invoice:InvoiceRecord|null;thobe:ThobeDraft;index:number;total:number;deliveryDate:string}){const collarCategory=thobe.collarMode==="قلاب"?"القلاب":thobe.collarMode==="سادة"?"الرقبة السادة":"",collarName=collarCategory?thobe.designs[collarCategory]?.name||thobe.collarMode:thobe.collarMode;return <article className="paper receipt-paper laundry-receipt" dir="rtl"><h2>أناقة التميز</h2><p>بطاقة المغسلة</p><hr/><div><span>رقم الفاتورة</span><b className="numeric">{invoice?sequenceNumber(invoice.invoiceNumber):"مسودة"}</b></div><div><span>رقم العميل</span><b className="numeric">{sequenceNumber(customer.code)}</b></div><div><span>اسم العميل</span><b>{customer.name}</b></div><div><span>الثوب</span><b className="numeric">{index+1} / {total}</b></div><div><span>نوع الثوب</span><b>{thobe.thobeType}</b></div><hr/><div><span>نوع الرقبة</span><b>{collarName}</b></div>{thobe.collarMode!=="بدون رقبة"&&<><div><span>محيط الرقبة</span><b className="numeric">{thobe.measurements["محيط الرقبة"]||"—"}</b></div>{thobe.collarMode==="قلاب"?<div><span>مقاس القلاب</span><b className="numeric">{thobe.measurements["مقاس القلاب الأول"]||"—"} — {thobe.measurements["مقاس القلاب الثاني"]||"—"}</b></div>:<div><span>مقاس الرقبة السادة</span><b className="numeric">{thobe.measurements["مقاس الرقبة السادة"]||"—"}</b></div>}<div><span>عدد أزرار الرقبة</span><b className="numeric">{thobe.neckButtonCount}</b></div><div><span>نوع أزرار الرقبة</span><b>{thobe.neckButtonType}</b></div></>}<div><span>نوع اليد</span><b>{thobe.sleeveMode}</b></div><div><span>تاريخ التسليم</span><b className="numeric">{deliveryDate||"—"}</b></div>{thobe.notes&&<><hr/><p className="laundry-note">ملاحظة: {thobe.notes}</p></>}<hr/><small>الثوب <span className="numeric">{index+1}</span> من <span className="numeric">{total}</span></small></article>}

  function ExtraReceiptSheet({transaction}:{transaction:ExtraTransaction}){return <article className="paper receipt-paper extra-receipt" dir="rtl"><h2>أناقة التميز</h2><p>فاتورة {transaction.transactionType}</p><hr/><div><span>رقم الفاتورة</span><b className="numeric">{transaction.id}</b></div><div><span>اسم الزبون</span><b>{transaction.customerName}</b></div>{transaction.customerPhone&&<div><span>رقم الجوال</span><b className="numeric">{transaction.customerPhone}</b></div>}<div><span>التاريخ</span><b className="numeric">{shortDateFormat.format(databaseDate(transaction.createdAt))}</b></div>{transaction.transactionType==="تصليح"&&<><div><span>عدد الثياب</span><b className="numeric">{transaction.quantity}</b></div>{transaction.workerName&&<div><span>العامل المنفذ</span><b>{transaction.workerName}</b></div>}</>}{transaction.transactionType==="بيع قماش"&&<><hr/><div><span>القماش</span><b>{transaction.fabricName} — {transaction.fabricColor}</b></div><div><span>الكمية</span><b className="numeric">{numberFormat.format(transaction.meters)} متر</b></div></>}{transaction.transactionType==="بيع جاهز"&&<><hr/><div><span>عدد القطع الجاهزة</span><b className="numeric">{numberFormat.format(transaction.quantity)}</b></div></>} {transaction.description&&<><hr/><p className="extra-receipt-note">{transaction.description}</p></>}<hr/><div><span>الإجمالي</span><b className="numeric">{numberFormat.format(transaction.totalPrice)} ر.س</b></div><div><span>طريقة الدفع</span><b>{transaction.paymentMethod}</b></div><hr/><small>شكرًا لاختياركم أناقة التميز</small></article>}

  function FinancialReportSheet({report,shopName,ownerName}:{report:DailyReport;shopName:string;ownerName:string}){const net=report.invoiceReceived+report.extraIncome-report.expenses;return <article className="paper a5-financial-sheet report-print-sheet" dir="rtl"><header><div><h2>{shopName||"TAILOR"}</h2><p>{report.periodLabel}</p></div><div><b className="numeric">{report.reportDate}</b><small>تاريخ إصدار التقرير: <span className="numeric">{shortDateFormat.format(new Date())}</span></small></div></header><section className="a5-report-grid"><div><span>قيمة الفواتير</span><b className="numeric">{numberFormat.format(report.invoiceSales)} ر.س</b></div><div><span>المقبوض</span><b className="numeric">{numberFormat.format(report.invoiceReceived)} ر.س</b></div><div><span>الدخل الإضافي</span><b className="numeric">{numberFormat.format(report.extraIncome)} ر.س</b></div><div><span>المصروفات ودفعات الموردين</span><b className="numeric">{numberFormat.format(report.expenses)} ر.س</b></div><div className="net"><span>الصافي</span><b className="numeric">{numberFormat.format(net)} ر.س</b></div></section><section className="a5-operation-grid"><p><span>العملاء الجدد</span><b className="numeric">{report.newCustomers}</b></p><p><span>عدد الفواتير</span><b className="numeric">{report.invoices}</b></p><p><span>الثياب المسجلة</span><b className="numeric">{report.thobes}</b></p><p><span>الثياب المسلمة</span><b className="numeric">{report.delivered}</b></p><p><span>قماش التفصيل</span><b className="numeric">{numberFormat.format(report.fabricUsed)} متر</b></p><p><span>القماش المباع</span><b className="numeric">{numberFormat.format(report.fabricSold)} متر</b></p></section><footer><span>اسم المسؤول: {ownerName||"________________"}</span><span>التوقيع: ____________________</span></footer></article>}

  function SupplierPaymentSheet({payment,shopName,ownerName}:{payment:SupplierPayment;shopName:string;ownerName:string}){return <article className="paper a5-financial-sheet supplier-payment-sheet" dir="rtl"><header><div><h2>{shopName||"TAILOR"}</h2><p>سند دفع مورد</p></div><div><b>رقم السند: <span className="numeric">{payment.id}</span></b><small className="numeric">{shortDateFormat.format(databaseDate(payment.createdAt))}</small></div></header><section className="supplier-payment-body"><p><span>اسم المورد / الموزع</span><b>{payment.supplierName}</b></p><p><span>المبلغ المدفوع</span><b className="numeric">{numberFormat.format(payment.amount)} ر.س</b></p><p><span>طريقة الدفع</span><b>{payment.paymentMethod}</b></p><p><span>البيان</span><b>{payment.notes||"دفعة حساب للمورد"}</b></p></section><footer className="signature-row"><div><span>صاحب المحل</span><b>{ownerName||"________________"}</b><i>التوقيع: ____________________</i></div><div><span>المورد / الموزع</span><b>{payment.supplierName}</b><i>التوقيع: ____________________</i></div></footer></article>}
