  function draftsFromInvoice(saved:SavedInvoice){
    const details=parseObject(saved.detailsJson);
    const storedUnit=details.unit==="سم"?"سم" as const:"إنش" as const;
    const rawThobes=Array.isArray(details.thobes)?details.thobes:[];
    const legacy={measurements:parseObject(saved.measurementsJson),fabric:parseObject(saved.fabricJson),fabricItemId:details.fabricItemId,fabricMeters:details.fabricMeters,designs:parseObject(saved.designsJson),thobeType:details.thobeType,sleeveMode:details.sleeveMode,collarMode:details.collarMode,neckButtonCount:details.neckButtonCount,neckButtonType:details.neckButtonType,workerName:details.workerName,sizeCategory:details.sizeCategory,sizeOverride:details.sizeOverride,cutPrice:details.cutPrice,cutPriceOverride:details.cutPriceOverride,notes:saved.notes};
    const sources=rawThobes.length?rawThobes:[legacy];
    const drafts=sources.map(source=>{
      const raw=objectValue(source),designs:Record<string,DesignOption|undefined>={},storedMeasurements=textRecord(raw.measurements);
      if(!storedMeasurements["طول الكبك"]&&storedMeasurements["طول الكباك"])storedMeasurements["طول الكبك"]=storedMeasurements["طول الكباك"];
      if(!storedMeasurements["عرض الكبك"]&&storedMeasurements["عرض الكباك"])storedMeasurements["عرض الكبك"]=storedMeasurements["عرض الكباك"];
      if(!storedMeasurements["خبنة"]&&storedMeasurements["الخانة تحت"])storedMeasurements["خبنة"]=storedMeasurements["الخانة تحت"];
      Object.entries(objectValue(raw.designs)).forEach(([category,id])=>{const normalizedCategory=category==="الكباك"?"الكبك":category,option=designOptions.find(item=>item.id===Number(id));if(option)designs[normalizedCategory]=option});
      const sleeve: SleeveMode=raw.sleeveMode==="كبك"||raw.sleeveMode==="كباك"?"كبك":"سادة";
      const collar: CollarMode=raw.collarMode==="بدون رقبة"?"بدون رقبة":raw.collarMode==="سادة"?"سادة":"قلاب";
      const buttonCount:"1"|"2"=String(raw.neckButtonCount)==="2"?"2":"1",buttonType:NeckButtonType=raw.neckButtonType==="بلاستيك"?"بلاستيك":"طقطق";
      const autoSize=autoThobeSize(storedMeasurements,storedUnit),storedSize:ThobeSize=raw.sizeCategory==="كبير"?"كبير":raw.sizeCategory==="صغير"?"صغير":autoSize;
      return {measurements:{...blankFields(measurementFields),...storedMeasurements},fabric:{...blankFields(fabricFields),...textRecord(raw.fabric)},fabricItemId:Number(raw.fabricItemId)>0?Number(raw.fabricItemId):null,fabricMeters:String(raw.fabricMeters||""),designs,thobeType:String(raw.thobeType||"سعودي"),sleeveMode:sleeve,collarMode:collar,neckButtonCount:buttonCount,neckButtonType:buttonType,workerName:String(raw.workerName||""),tailorName:String(raw.tailorName||""),sizeCategory:storedSize,sizeOverride:Boolean(raw.sizeOverride),cutPrice:String(raw.cutPrice||""),cutPriceOverride:Boolean(raw.cutPriceOverride),notes:String(raw.notes??saved.notes??"")} satisfies ThobeDraft;
    });
    while(drafts.length<Math.max(1,saved.totalThobes))drafts.push(cloneThobe(drafts[0]));
    return {drafts,unit:storedUnit};
  }
