  const visibleFinanceEntries=(finance?.entries||[]).filter(item=>!financeFilterDate||dayKey(databaseDate(item.createdAt))===financeFilterDate);const selectedAccount=workerAccounts.find(item=>item.worker.id===accountWorkerId)||null;const fullWorkerTimeline=selectedAccount?workerTimeline(selectedAccount,dateInputValue(today)):[];const accountYear=accountDate.slice(0,4),accountMonth=accountDate.slice(0,7);const rangeStart=accountPeriod==="all"?"":accountPeriod==="day"?accountDate:accountPeriod==="month"?accountMonth+"-01":accountYear+"-01-01";const rangeEnd=accountPeriod==="all"?"9999-12-31":accountPeriod==="day"?accountDate:accountPeriod==="month"?accountMonth+"-"+String(new Date(Number(accountYear),Number(accountMonth.slice(5,7)),0).getDate()).padStart(2,"0"):accountYear+"-12-31";const accountOpening=fullWorkerTimeline.filter(item=>item.createdAt.slice(0,10)<rangeStart).reduce((sum,item)=>sum+item.amount,0);let runningAccountBalance=0;const visibleWorkerTimeline=fullWorkerTimeline.map(item=>{runningAccountBalance+=item.amount;return {...item,runningBalance:runningAccountBalance}}).filter(item=>item.createdAt.slice(0,10)>=rangeStart&&item.createdAt.slice(0,10)<=rangeEnd);const accountCredits=visibleWorkerTimeline.reduce((sum,item)=>sum+Math.max(0,item.amount),0),accountDraws=visibleWorkerTimeline.reduce((sum,item)=>sum+Math.max(0,-item.amount),0);const accountClosing=accountOpening+accountCredits-accountDraws;const availableTailorNames=workers.filter(item=>item.role==="خياط"&&item.active);
